import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CQIwe17B.js";const g=JSON.parse('{"title":"Master Feature Inventory: Natours (Wanderly)","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),i={name:"01-features.md"};function r(n,e,d,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="master-feature-inventory-natours-wanderly" tabindex="-1">Master Feature Inventory: Natours (Wanderly) <a class="header-anchor" href="#master-feature-inventory-natours-wanderly" aria-label="Permalink to &quot;Master Feature Inventory: Natours (Wanderly)&quot;">​</a></h1><h2 id="subsystem-matrix" tabindex="-1">Subsystem Matrix <a class="header-anchor" href="#subsystem-matrix" aria-label="Permalink to &quot;Subsystem Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature ID</th><th>Feature Name</th><th>Core Source Files</th><th>Primary Architectural Mechanism</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Slanted Hero &amp; Keyframe CTA</td><td><code>sass/layout/_header.scss</code>, <code>sass/base/_animations.scss</code>, <code>sass/components/_button.scss</code></td><td>CSS <code>clip-path: polygon()</code>, <code>@keyframes moveInLeft/Right/Bottom</code>, GPU hardware acceleration.</td></tr><tr><td><strong>F2</strong></td><td>Pure CSS Navigation Hack</td><td><code>sass/layout/_navigation.scss</code></td><td>Checkbox hack (<code>input:checked ~ .navigation__background</code>), radial gradient scale(80).</td></tr><tr><td><strong>F3</strong></td><td>3D Rotating Tour Cards</td><td><code>sass/components/_card.scss</code></td><td><code>perspective: 150rem</code>, <code>rotateY(180deg)</code>, <code>backface-visibility: hidden</code>.</td></tr><tr><td><strong>F4</strong></td><td>Pure CSS Modal Booking Popup</td><td><code>sass/components/_popup.scss</code></td><td>CSS <code>:target</code> pseudo-class, URL hash activation, backdrop filter blur.</td></tr><tr><td><strong>F5</strong></td><td>Mathematical Float Grid</td><td><code>sass/layout/_grid.scss</code>, <code>sass/abstracts/_mixins.scss</code></td><td>Dynamic <code>calc()</code> formulas, micro-clearfix, responsive breakpoint collapsing.</td></tr><tr><td><strong>F6</strong></td><td>Skewed Testimonial Stories</td><td><code>sass/components/_story.scss</code></td><td>Inverse <code>skewX(-12deg)</code> container with <code>shape-outside: circle()</code> image wrap.</td></tr><tr><td><strong>F7</strong></td><td>Fullscreen Ambient Background Video</td><td><code>sass/components/_bg-video.scss</code></td><td>HTML5 <code>&lt;video&gt;</code> tag with <code>object-fit: cover</code> and low-opacity overlay.</td></tr><tr><td><strong>F8</strong></td><td>Floating Label Booking Form</td><td><code>sass/components/_form.scss</code></td><td><code>:placeholder-shown</code> pseudo-class sibling selector, custom animated radio buttons.</td></tr></tbody></table><hr><h2 id="detailed-feature-specifications" tabindex="-1">Detailed Feature Specifications <a class="header-anchor" href="#detailed-feature-specifications" aria-label="Permalink to &quot;Detailed Feature Specifications&quot;">​</a></h2><h3 id="f1-slanted-hero-keyframe-cta" tabindex="-1">F1: Slanted Hero &amp; Keyframe CTA <a class="header-anchor" href="#f1-slanted-hero-keyframe-cta" aria-label="Permalink to &quot;F1: Slanted Hero &amp; Keyframe CTA&quot;">​</a></h3><ul><li><strong>Description</strong>: Visual entry point featuring an angled polygonal bottom edge (<code>clip-path: polygon(0 0, 100% 0, 100% 75vh, 0 100%)</code>) and typography entrance animations.</li><li><strong>Functions &amp; Mixins</strong>: <code>@mixin respond(phone)</code> in <code>_mixins.scss:L39</code> adapts polygon angle on mobile devices to prevent excessive content cropping.</li><li><strong>Edge Cases</strong>: Older browsers lacking <code>clip-path</code> support display standard rectangular box via graceful degradation.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built the hero section in <code>_header.scss</code> to deliver an immediate premium visual impact without any external animation libraries. I used CSS <code>clip-path: polygon()</code> to cut the bottom edge of the hero into a dynamic 75-vh angled slope. For the typography, I wrote custom CSS <code>@keyframes</code> in <code>_animations.scss</code> that animate both horizontal translation and opacity, timed with a cubic-bezier easing curve. The CTA button includes an animated pseudo-element ripple that expands and fades on hover. Because everything is handled by CSS transforms and opacity, the animation runs exclusively on the GPU compositor thread with zero layout reflows.&quot;</p></blockquote><hr><h3 id="f2-pure-css-navigation-hack" tabindex="-1">F2: Pure CSS Navigation Hack <a class="header-anchor" href="#f2-pure-css-navigation-hack" aria-label="Permalink to &quot;F2: Pure CSS Navigation Hack&quot;">​</a></h3><ul><li><strong>Description</strong>: Fullscreen mobile-friendly navigation overlay triggered completely by native HTML checkbox state without a single line of JavaScript.</li><li><strong>Trace</strong>: Checkbox <code>&lt;input type=&quot;checkbox&quot; id=&quot;navi-toggle&quot;&gt;</code> followed by <code>&lt;label for=&quot;navi-toggle&quot;&gt;</code> and <code>&lt;div class=&quot;navigation__background&quot;&gt;</code>.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;To achieve an interactive fullscreen menu without JavaScript, I implemented the CSS checkbox hack in <code>_navigation.scss</code>. An invisible native checkbox is bound to an accessible circular button label. When the user clicks the hamburger icon, the checkbox toggles to <code>:checked</code>, which triggers the adjacent sibling combinator to scale an underlying green radial gradient circle from 6rem to eighty times its size. This instantly floods the viewport with color while the navigation links fade into view with cubic-bezier timing. If a user clicks outside or on a link, the checkbox state resets, collapsing the overlay smoothly back into the circular icon.&quot;</p></blockquote><hr><h3 id="f3-3d-rotating-tour-cards" tabindex="-1">F3: 3D Rotating Tour Cards <a class="header-anchor" href="#f3-3d-rotating-tour-cards" aria-label="Permalink to &quot;F3: 3D Rotating Tour Cards&quot;">​</a></h3><ul><li><strong>Description</strong>: Three-dimensional interactive cards showcasing nature tour packages. Hovering rotates the card 180 degrees along the Y-axis to reveal pricing and booking details.</li><li><strong>Trace</strong>: <code>sass/components/_card.scss</code>.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;In <code>_card.scss</code>, I engineered the 3D rotating tour cards using native CSS 3D transforms. The parent container sets a <code>perspective: 150rem</code> to establish realistic visual depth. Inside, I created two mirrored card sides—front and back—positioned absolutely on top of each other with <code>backface-visibility: hidden</code>. When hovered, the front face rotates from 0 to negative 180 degrees, while the back face rotates from positive 180 degrees to 0. For mobile touchscreens where hover states don&#39;t exist, I added a media query for <code>hover: none</code> that automatically flattens the card into a single vertical card layout with the price immediately visible.&quot;</p></blockquote><hr><h3 id="f4-pure-css-modal-booking-popup" tabindex="-1">F4: Pure CSS Modal Booking Popup <a class="header-anchor" href="#f4-pure-css-modal-booking-popup" aria-label="Permalink to &quot;F4: Pure CSS Modal Booking Popup&quot;">​</a></h3><ul><li><strong>Description</strong>: Fullscreen booking modal dialog triggered when a user clicks any &quot;Book now!&quot; button.</li><li><strong>Trace</strong>: <code>sass/components/_popup.scss</code>. Anchor links set window hash <code>#popup</code>.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;For the booking modal in <code>_popup.scss</code>, I eliminated the need for modal management JavaScript by utilizing the native CSS <code>:target</code> pseudo-class. When an explorer clicks &#39;Book now&#39;, the URL hash updates to <code>#popup</code>. The CSS selector <code>.popup:target</code> immediately activates, transitioning the backdrop from opacity zero to one and scaling the modal dialog box from 0.25 to full scale with a smooth bounce. Clicking the close button or anywhere outside the modal routes the anchor back to the tours section, immediately dismissing the target state and hiding the modal.&quot;</p></blockquote>',20)])])}const p=t(i,[["render",r]]);export{g as __pageData,p as default};
